package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.collaboration.course.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class CourseStoreIntegrationTest {
 StudyStoreIntegrationTest parent;GroupStoreIntegrationTest f;CourseStore store;UUID group,space;
 @BeforeEach void setup(){parent=new StudyStoreIntegrationTest();parent.setup();f=parent.f;group=parent.group;space=parent.space;store=new CourseStore(f.source,Clock.systemUTC());}
 CourseStore.Result create(String key){return store.create(group,space,f.owner,key,"Course <script>","공유 목적",f.trace);}
 StudyStore.Study study(){return parent.create(f.key()).study();}
 void status(int code,org.junit.jupiter.api.function.Executable op){parent.status(code,op);}
 int events(UUID id){return parent.events(id);}
 CourseStore.Course curriculum(CourseStore.Course v,UUID... ids){return store.curriculum(group,space,v.courseId(),f.owner,v.version(),List.of(ids),f.trace);}
 CourseStore.Course state(CourseStore.Course v,String state){return store.state(group,space,v.courseId(),f.owner,v.version(),state,f.trace);}
 @Test void orderedCurriculumAndImmutableProvenanceCommitWithAuditAndProtobuf()throws Exception{
  var a=study();var b=study();var c=create(f.key()).course();assertEquals(7,c.courseId().version());assertEquals("DRAFT",c.state());assertEquals("PRIVATE",c.visibility());var v=curriculum(c,b.studyId(),a.studyId());assertEquals(List.of(b.studyId(),a.studyId()),v.studies().stream().map(CourseStore.StudyReference::studyId).toList());assertEquals(v,store.get(group,space,c.courseId()));assertEquals(List.of(b.studyId(),a.studyId()),f.jdbc.queryForList("SELECT study_id FROM course_study WHERE course_id=? ORDER BY position",UUID.class,c.courseId()));
  var e=CourseEnvelopeV1.parseFrom(f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=? AND type='CourseCurriculumChanged'",byte[].class,c.courseId()));var payload=CourseSnapshotV1.parseFrom(e.getPayload());assertEquals("Course",e.getAggregateType());assertEquals(f.trace,e.getTraceId());assertEquals(space.toString(),e.getSpaceId());assertEquals(group.toString(),payload.getGroupId());assertEquals(f.owner.toString(),e.getActorId());assertEquals(2,payload.getStudiesCount());assertEquals(b.studyId().toString(),payload.getStudies(0).getStudyId());assertEquals(1,payload.getStudies(0).getStudyVersion());assertEquals(v,store.history(group,space,c.courseId(),Long.MAX_VALUE,3).items().getFirst().snapshot());assertEquals(a,parent.store.get(group,space,a.studyId()));
 }
 @Test void originalCreationRetryReturnsCurrentAfterEditsArchiveAndRestart(){String key=f.key();var c=create(key).course();assertFalse(create(key).created());var changed=store.metadata(group,space,c.courseId(),f.owner,1,"Corrected","",f.trace);status(409,()->store.create(group,space,f.owner,key,"Other","",f.trace));var archived=state(changed,"RETIRED");assertEquals(archived,new CourseStore(f.source,Clock.systemUTC()).create(group,space,f.owner,key,c.title(),c.description(),f.trace).course());assertEquals(3,events(c.courseId()));}
 @Test void lifecycleRequiresNonemptyCurrentSourcesAndFreezesStartedCurriculum(){var c=create(f.key()).course();status(409,()->state(c,"ACTIVE"));status(409,()->state(c,"COMPLETED"));var a=study();var v=curriculum(c,a.studyId());var active=state(v,"ACTIVE");status(409,()->curriculum(active,a.studyId()));assertEquals(active,state(active,"ACTIVE"));var done=state(active,"COMPLETED");status(409,()->state(done,"ACTIVE"));var corrected=store.metadata(group,space,c.courseId(),f.owner,done.version(),"Correction","",f.trace);var retired=state(corrected,"RETIRED");assertEquals(retired,state(retired,"RETIRED"));status(409,()->curriculum(retired));status(409,()->store.metadata(group,space,c.courseId(),f.owner,retired.version(),"Restore","",f.trace));assertEquals("PLANNED",parent.store.get(group,space,a.studyId()).state());}
 @Test void sourceChangesDoNotRewriteCourseSnapshotsAndDraftRefreshPinsLatest(){var a=study();var c=curriculum(create(f.key()).course(),a.studyId());var edited=parent.store.metadata(group,space,a.studyId(),f.owner,1,"Renamed","",f.trace);assertEquals(a.title(),store.get(group,space,c.courseId()).studies().getFirst().title());var refreshed=curriculum(c,a.studyId());assertEquals(edited.version(),refreshed.studies().getFirst().studyVersion());assertEquals(edited.title(),refreshed.studies().getFirst().title());assertEquals(refreshed,curriculum(refreshed,a.studyId()));parent.store.state(group,space,a.studyId(),f.owner,2,"RETIRED",f.trace);status(409,()->state(refreshed,"ACTIVE"));status(409,()->curriculum(refreshed,a.studyId()));assertEquals(a.title(),store.history(group,space,c.courseId(),3,3).items().getFirst().snapshot().studies().getFirst().title());assertTrue(curriculum(refreshed).studies().isEmpty());}
 @Test void referencesRejectDuplicatesWrongGroupSpaceAndArchivedStudy(){var c=create(f.key()).course();var a=study();status(400,()->curriculum(c,a.studyId(),a.studyId()));status(404,()->curriculum(c,f.ids.next()));status(404,()->store.curriculum(group,f.ids.next(),c.courseId(),f.owner,1,List.of(a.studyId()),f.trace));var another=new StudyStoreIntegrationTest();another.setup();var foreign=another.create(another.f.key()).study();status(404,()->curriculum(c,foreign.studyId()));parent.store.state(group,space,a.studyId(),f.owner,1,"RETIRED",f.trace);status(409,()->curriculum(c,a.studyId()));assertEquals(c,store.get(group,space,c.courseId()));assertEquals(1,events(c.courseId()));}
 @Test void fiftySourcesBoundAndReorderRemainAtomic(){var c=create(f.key()).course();var ids=new ArrayList<UUID>();for(int n=0;n<50;n++)ids.add(study().studyId());var v=store.curriculum(group,space,c.courseId(),f.owner,1,ids,f.trace);assertEquals(50,v.studies().size());ids.add(f.ids.next());status(400,()->store.curriculum(group,space,c.courseId(),f.owner,2,ids,f.trace));assertEquals(v,store.get(group,space,c.courseId()));ids.removeLast();Collections.reverse(ids);assertEquals(ids,store.curriculum(group,space,c.courseId(),f.owner,2,ids,f.trace).studies().stream().map(CourseStore.StudyReference::studyId).toList());}
 @Test void staleNoOpAndKeysetHistoryHaveIndependentCourseVersion(){var c=create(f.key()).course();assertEquals(c,store.metadata(group,space,c.courseId(),f.owner,1,c.title(),c.description(),f.trace));assertEquals(c,curriculum(c));var a=study();var v=curriculum(c,a.studyId());status(412,()->curriculum(c,a.studyId()));var next=state(v,"ACTIVE");var page=store.history(group,space,c.courseId(),Long.MAX_VALUE,2);assertEquals(List.of(3L,2L),page.items().stream().map(CourseStore.Revision::version).toList());assertEquals(1,store.history(group,space,c.courseId(),page.nextBefore(),2).items().size());create(f.key());create(f.key());var catalog=store.list(group,space,null,2);assertEquals(2,catalog.items().size());assertEquals(1,store.list(group,space,catalog.nextAfter(),2).items().size());assertEquals(1,parent.store.get(group,space,a.studyId()).version());}
 @Test void concurrentCreateAndMetadataCurriculumHaveOneWinner()throws Exception{var a=study();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);String key=f.key();var x=pool.submit(()->{barrier.await();return create(key);});var y=pool.submit(()->{barrier.await();return create(key);});var c=x.get();var d=y.get();assertNotEquals(c.created(),d.created());assertEquals(c.course(),d.course());var one=pool.submit(()->{barrier.await();try{curriculum(c.course(),a.studyId());return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}});var two=pool.submit(()->{barrier.await();try{store.metadata(group,space,c.course().courseId(),f.owner,1,"Changed","",f.trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}});assertNotEquals(one.get(),two.get());assertEquals(2,events(c.course().courseId()));}}
 @Test void sourceRetirementAndCourseStartSerializeWithoutDeadlock()throws Exception{var a=study();var c=curriculum(create(f.key()).course(),a.studyId());try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var x=pool.submit(()->{barrier.await();return parent.store.state(group,space,a.studyId(),f.owner,1,"RETIRED",f.trace);});var y=pool.submit(()->{barrier.await();try{return state(c,"ACTIVE");}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals("RETIRED",x.get(20,TimeUnit.SECONDS).state());var result=y.get(20,TimeUnit.SECONDS);assertEquals(result==null?"DRAFT":"ACTIVE",store.get(group,space,c.courseId()).state());assertEquals(a.studyId(),store.get(group,space,c.courseId()).studies().getFirst().studyId());}}
 @Test void outboxFailureRollsBackCurrentRevisionAndCurriculumReplacement(){var a=study();var b=study();var c=curriculum(create(f.key()).course(),a.studyId());String name="course_fail_"+c.courseId().toString().replace("-","");f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+" CHECK(aggregatetype<>'course' OR trace_id<>'"+f.trace+"') NOT VALID");try{assertThrows(RuntimeException.class,()->create(f.key()));assertThrows(RuntimeException.class,()->curriculum(c,b.studyId()));assertThrows(RuntimeException.class,()->state(c,"ACTIVE"));assertEquals(c,store.get(group,space,c.courseId()));assertEquals(List.of(a.studyId()),f.jdbc.queryForList("SELECT study_id FROM course_study WHERE course_id=?",UUID.class,c.courseId()));assertEquals(2,events(c.courseId()));assertEquals(2,store.history(group,space,c.courseId(),Long.MAX_VALUE,3).items().size());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
}
